mapper.select:
select r.id, r.member_id, r.parent_order_no, r.owner_type, r.owner_id, r.payment_status,
       r.registration_status, r.wechat_payment_amount, r.payable_amount
from cms_registration r where r.member_id=#{memberId}
and r.id in #{id}
and  order by r.id

mapper.update:
update user_invoice_title set is_default = 0
where member_id = #{memberId} and del_flag = 0 and is_default = 1
and id != #{exceptId}

mapper.sql:
where r.member_id = #{memberId} and r.payment_status = 2 and r.registration_status = 2 and r.wechat_payment_amount > 0 and and not exists ( select 1 from cms_registration child where r.parent_order_no is not null and r.parent_order_no != '' and child.parent_order_no=r.parent_order_no and (child.member_id != r.member_id or child.owner_type != r.owner_type or child.owner_id != r.owner_id or child.payment_status != 2 or child.registration_status != 2))
and r.id in #{oid}
and not exists ( select 1 from refund_application ra where ra.source_type = 'registration' and (ra.source_id = r.id or (r.parent_order_no is not null and r.parent_order_no != '' and exists (select 1 from cms_registration sibling where sibling.parent_order_no=r.parent_order_no and sibling.id=ra.source_id))) and ra.del_flag = 0 and ra.status in (0, 1)) and not exists ( select 1 from user_invoice_application_order o where o.order_source = 'registration' and o.active_key = 1 and (o.order_id = r.id or (r.parent_order_no is not null and r.parent_order_no != '' and exists (select 1 from cms_registration sibling where sibling.parent_order_no=r.parent_order_no and sibling.id=o.order_id))))
